#include <bits/stdc++.h>
using namespace std;

const long long MOD1 = 1e9+7;
const long long MOD2 = 998244353;
const int MAX_LEVEL = 7;
const long long BASE_VAL = 1000000;

long long max_n, order_counter;
int result;
int prefix_sum[MAX_LEVEL];
vector<int> digit_list[MAX_LEVEL];

void build_sequences(int start_value, int level) {
    order_counter++;
    digit_list[level].push_back(((order_counter - start_value) % MOD2 + MOD2) % MOD2);
    prefix_sum[level] = (prefix_sum[level] + digit_list[level].back()) % MOD1;
    if (level == 6) return;
    for (int digit = 0; digit <= 9; digit++) {
        build_sequences(start_value * 10 + digit, level + 1);
    }
}

void traverse(long long x) {
    if (x > max_n) return;
    if (x * BASE_VAL + BASE_VAL - 1 <= max_n && x * BASE_VAL * 10 > max_n) {
        long long saved_order = order_counter;
        for (int depth = 0, factor = 1; depth <= 6; depth++, factor *= 10) {
            int size = (int)digit_list[depth].size();
            int diff = (int)(((saved_order - x * factor) % MOD2 + MOD2) % MOD2);
            int pos = (int)(lower_bound(digit_list[depth].begin(), digit_list[depth].end(), (int)(MOD2 - diff)) - digit_list[depth].begin());
            result = (result + 1LL * diff * size + prefix_sum[depth]) % MOD1;
            result = (result - 1LL * MOD2 * (size - pos) % MOD1 + MOD1) % MOD1;
            order_counter += size;
        }
        return;
    }
    order_counter++;
    result = (result + ((order_counter - x) % MOD2 + MOD2) % MOD2) % MOD1;
    for (int digit = 0; digit <= 9; digit++) {
        traverse(x * 10 + digit);
    }
}

int main() {
    cin >> max_n;
    order_counter = 0;
    build_sequences(0, 0);
    for (int i = 0; i <= 6; i++) {
        sort(digit_list[i].begin(), digit_list[i].end());
    }
    order_counter = 0;
    for (int i = 1; i <= 9; i++) {
        traverse(i);
    }
    cout << result << "\n";
    return 0;
}
